/* SmartLearn Native Color Classes */
.sl-text-primary { color: var(--smartlearn-primary) !important; }
.sl-text-emphasis { color: var(--smartlearn-text) !important; }
.sl-text-muted { color: var(--smartlearn-text-muted) !important; }
.sl-bg-main { background-color: var(--smartlearn-bg) !important; }
.sl-bg-card { background-color: var(--smartlearn-card-bg) !important; border: 1px solid var(--smartlearn-card-border) !important; }
.sl-bg-primary { background-color: var(--smartlearn-primary) !important; }
.sl-cta-minimal .sl-btn-primary { background-color: var(--smartlearn-primary) !important; border-color: var(--smartlearn-primary) !important; color: #fff !important; transition: transform 0.3s ease, box-shadow 0.3s ease; }
.sl-cta-minimal .sl-btn-primary:hover { transform: translateY(-3px); box-shadow: 0 10px 20px rgba(0,0,0,0.2) !important; filter: brightness(0.9); }

.sl-cta-minimal .sl-btn-minimal {
    color: var(--smartlearn-primary);
    position: relative;
    padding-bottom: 5px;
    transition: color 0.3s ease;
}
.sl-cta-minimal .sl-btn-minimal-underline {
    position: absolute;
    bottom: 0;
    left: 0;
    width: 100%;
    height: 2px;
    background-color: var(--smartlearn-primary);
    transform-origin: right;
    transform: scaleX(0);
    transition: transform 0.3s ease;
}
.sl-cta-minimal .sl-btn-minimal:hover .sl-btn-minimal-underline {
    transform-origin: left;
    transform: scaleX(1);
}
.sl-cta-minimal .sl-btn-minimal:hover {
    color: var(--smartlearn-primary);
    filter: brightness(0.9);
}
@media (prefers-reduced-motion: reduce) {
    .sl-cta-minimal .sl-btn-minimal-underline { transition: none; display: none; }
    .sl-cta-minimal .sl-btn-minimal:hover { text-decoration: underline !important; }
}
